-- Name: apply_department_rls(regclass, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_department_rls(tbl regclass, dept_col text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    short_name TEXT := regexp_replace(tbl::text, '^.*\.', '');
    policy_name TEXT := 'dept_scope_' || short_name;
BEGIN
    -- Department policy is additive to tenant isolation; both must pass.
    -- Postgres applies all permissive policies as OR within action, so we
    -- must declare this RESTRICTIVE so it AND-combines with tenant policy.
    EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', tbl);
    EXECUTE format('DROP POLICY IF EXISTS %I ON %s', policy_name, tbl);

    EXECUTE format(
        'CREATE POLICY %I ON %s '
        || 'AS RESTRICTIVE '
        || 'USING (check_department_access(%I)) '
        || 'WITH CHECK (check_department_access(%I))',
        policy_name, tbl, dept_col, dept_col
    );
END $$;

CREATE FUNCTION public.apply_tenant_rls(tbl regclass) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    short_name TEXT := regexp_replace(tbl::text, '^.*\.', '');
    policy_name TEXT := 'tenant_isolation_' || short_name;
BEGIN
    EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', tbl);

    -- Drop existing policy with same name to make this idempotent
    EXECUTE format('DROP POLICY IF EXISTS %I ON %s', policy_name, tbl);

    EXECUTE format(
        'CREATE POLICY %I ON %s '
        || 'USING (tenant_id::text = current_setting(''app.tenant_id'', true)) '
        || 'WITH CHECK (tenant_id::text = current_setting(''app.tenant_id'', true))',
        policy_name, tbl
    );
END $$;

CREATE FUNCTION public.apply_tenant_rls_with_global(tbl regclass) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    short_name TEXT := regexp_replace(tbl::text, '^.*\.', '');
    policy_name TEXT := 'tenant_isolation_' || short_name;
BEGIN
    EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', tbl);
    EXECUTE format('DROP POLICY IF EXISTS %I ON %s', policy_name, tbl);

    EXECUTE format(
        'CREATE POLICY %I ON %s '
        || 'USING (tenant_id IS NULL OR tenant_id::text = current_setting(''app.tenant_id'', true)) '
        || 'WITH CHECK (tenant_id IS NULL OR tenant_id::text = current_setting(''app.tenant_id'', true))',
        policy_name, tbl
    );
END $$;

CREATE FUNCTION public.audit_log_hash_chain() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    last_hash TEXT;
    canonical TEXT;
BEGIN
    -- pg_advisory_xact_lock prevents concurrent inserts for the same
    -- tenant from racing on prev_hash lookup. Cross-tenant chains are
    -- independent so we lock by tenant_id only.
    PERFORM pg_advisory_xact_lock(hashtext('audit_chain'), hashtext(NEW.tenant_id::text));

    SELECT hash INTO last_hash
    FROM audit_log
    WHERE tenant_id = NEW.tenant_id
    ORDER BY created_at DESC, id DESC
    LIMIT 1;

    NEW.prev_hash := COALESCE(last_hash, '');

    -- Build canonical payload — keys sorted, no whitespace.
    canonical := jsonb_build_object(
        'tenant_id',  NEW.tenant_id::text,
        'user_id',    COALESCE(NEW.user_id::text, ''),
        'action',     NEW.action,
        'entity_type', NEW.entity_type,
        'entity_id',  COALESCE(NEW.entity_id::text, ''),
        'old_values', COALESCE(NEW.old_values::text, ''),
        'new_values', COALESCE(NEW.new_values::text, ''),
        'ip_address', COALESCE(NEW.ip_address, ''),
        'created_at', NEW.created_at::text,
        'prev_hash',  NEW.prev_hash
    )::text;

    NEW.hash_input_canonical := canonical;
    NEW.hash := encode(digest(canonical, 'sha256'), 'hex');

    RETURN NEW;
END;
$$;

CREATE FUNCTION public.audit_trigger_func() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_tenant_id     UUID;
    v_user_id       UUID;
    v_ip_address    TEXT;
    v_user_agent    TEXT;
    v_session_id    UUID;
    v_correlation   UUID;
    v_old_values    JSONB;
    v_new_values    JSONB;
    v_entity_id     UUID;
    v_skip          BOOLEAN := false;
BEGIN
    -- Read context from session GUCs (set by application middleware)
    BEGIN
        v_tenant_id := NULLIF(current_setting('app.tenant_id', true), '')::UUID;
    EXCEPTION WHEN OTHERS THEN v_tenant_id := NULL;
    END;
    BEGIN
        v_user_id := NULLIF(current_setting('app.user_id', true), '')::UUID;
    EXCEPTION WHEN OTHERS THEN v_user_id := NULL;
    END;
    BEGIN
        v_ip_address := NULLIF(current_setting('app.ip_address', true), '');
    EXCEPTION WHEN OTHERS THEN v_ip_address := NULL;
    END;
    BEGIN
        v_user_agent := NULLIF(current_setting('app.user_agent', true), '');
    EXCEPTION WHEN OTHERS THEN v_user_agent := NULL;
    END;
    BEGIN
        v_session_id := NULLIF(current_setting('app.session_id', true), '')::UUID;
    EXCEPTION WHEN OTHERS THEN v_session_id := NULL;
    END;
    BEGIN
        v_correlation := NULLIF(current_setting('app.correlation_id', true), '')::UUID;
    EXCEPTION WHEN OTHERS THEN v_correlation := NULL;
    END;

    -- Without tenant context we cannot audit; bail out silently rather
    -- than failing the underlying write.
    IF v_tenant_id IS NULL THEN
        RETURN COALESCE(NEW, OLD);
    END IF;

    IF (TG_OP = 'INSERT') THEN
        v_entity_id := (row_to_json(NEW)->>'id')::UUID;
        v_new_values := to_jsonb(NEW);
    ELSIF (TG_OP = 'UPDATE') THEN
        v_entity_id := (row_to_json(NEW)->>'id')::UUID;
        v_old_values := to_jsonb(OLD);
        v_new_values := to_jsonb(NEW);
        -- Skip no-op updates that only changed updated_at
        IF v_old_values - 'updated_at' = v_new_values - 'updated_at' THEN
            v_skip := true;
        END IF;
    ELSIF (TG_OP = 'DELETE') THEN
        v_entity_id := (row_to_json(OLD)->>'id')::UUID;
        v_old_values := to_jsonb(OLD);
    END IF;

    -- HTTP middleware dedup: if we have a correlation_id and an audit row
    -- already exists for this correlation+entity within the last 5s, skip
    IF NOT v_skip AND v_correlation IS NOT NULL THEN
        IF EXISTS (
            SELECT 1 FROM audit_log
            WHERE correlation_id = v_correlation
              AND entity_id IS NOT DISTINCT FROM v_entity_id
              AND entity_type = TG_TABLE_NAME
              AND created_at > now() - INTERVAL '5 seconds'
        ) THEN
            v_skip := true;
        END IF;
    END IF;

    IF NOT v_skip THEN
        INSERT INTO audit_log (
            tenant_id, user_id, action, entity_type, entity_id,
            old_values, new_values, ip_address, user_agent,
            session_id, correlation_id, hash
        ) VALUES (
            v_tenant_id, v_user_id, TG_OP, TG_TABLE_NAME, v_entity_id,
            v_old_values, v_new_values, v_ip_address, v_user_agent,
            v_session_id, v_correlation, NULL
        );
    END IF;

    RETURN COALESCE(NEW, OLD);
END $$;

CREATE FUNCTION public.bump_perm_version_on_group_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    IF NEW.permissions IS DISTINCT FROM OLD.permissions THEN
        UPDATE users SET perm_version = perm_version + 1
        WHERE id IN (SELECT user_id FROM access_group_members WHERE group_id = NEW.id);
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION public.bump_perm_version_on_membership() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        UPDATE users SET perm_version = perm_version + 1 WHERE id = OLD.user_id;
        RETURN OLD;
    ELSIF TG_OP = 'UPDATE' THEN
        -- Only when the row's effective membership changed (soft-delete/restore or
        -- expiry) — not on unrelated column touches.
        IF NEW.deleted_at IS DISTINCT FROM OLD.deleted_at
            OR NEW.expires_at IS DISTINCT FROM OLD.expires_at THEN
            UPDATE users SET perm_version = perm_version + 1 WHERE id = NEW.user_id;
        END IF;
        RETURN NEW;
    END IF;
    UPDATE users SET perm_version = perm_version + 1 WHERE id = NEW.user_id;
    RETURN NEW;
END;
$$;

CREATE FUNCTION public.bump_perm_version_on_role_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    IF NEW.permissions IS DISTINCT FROM OLD.permissions THEN
        UPDATE users SET perm_version = perm_version + 1
        WHERE tenant_id = NEW.tenant_id AND role::text = NEW.code;
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION public.check_department_access(dept_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    dept_ids_raw TEXT;
    dept_ids UUID[];
BEGIN
    dept_ids_raw := current_setting('app.user_department_ids', true);
    IF dept_ids_raw IS NULL OR dept_ids_raw = '' OR dept_ids_raw = '{}' THEN
        RETURN TRUE;  -- no restriction
    END IF;
    dept_ids := dept_ids_raw::UUID[];
    RETURN dept_id = ANY(dept_ids) OR dept_id IS NULL;
END;
$$;

CREATE FUNCTION public.ensure_partitions() RETURNS void
    LANGUAGE plpgsql
    AS $_$
DECLARE
    cfg          record;
    is_parent    boolean;
    step         interval;
    name_fmt     text;
    base         date;
    p_start      date;
    p_end        date;
    child        text;
    i            integer;
    cutoff       date;
    child_rec    record;
    child_period date;
BEGIN
    FOR cfg IN SELECT * FROM partition_config LOOP
        -- Only operate on genuine partitioned parents (relkind 'p').
        SELECT (c.relkind = 'p') INTO is_parent
        FROM pg_class c
        JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE c.relname = cfg.table_name AND n.nspname = 'public';
        IF is_parent IS NOT TRUE THEN
            CONTINUE;
        END IF;

        IF cfg.partition_interval = 'year' THEN
            step := interval '1 year';
            name_fmt := 'YYYY';
            base := date_trunc('year', now())::date;
        ELSE
            step := interval '1 month';
            name_fmt := 'YYYYMM';
            base := date_trunc('month', now())::date;
        END IF;

        -- DEFAULT safety net so an insert never fails for an un-created range.
        child := format('%s_default', cfg.table_name);
        EXECUTE format('CREATE TABLE IF NOT EXISTS %I PARTITION OF %I DEFAULT',
                       child, cfg.table_name);

        -- Current + premake future partitions.
        FOR i IN 0 .. cfg.premake LOOP
            p_start := base + (step * i);
            p_end   := p_start + step;
            child   := format('%s_p%s', cfg.table_name, to_char(p_start, name_fmt));
            EXECUTE format(
                'CREATE TABLE IF NOT EXISTS %I PARTITION OF %I FOR VALUES FROM (%L) TO (%L)',
                child, cfg.table_name, p_start::text, p_end::text);
        END LOOP;

        -- Retention: retire partitions whose range ends before the cutoff.
        IF cfg.retention_months IS NOT NULL THEN
            cutoff := date_trunc('month', now())::date
                      - make_interval(months => cfg.retention_months);
            FOR child_rec IN
                SELECT c.relname
                FROM pg_inherits inh
                JOIN pg_class c ON c.oid = inh.inhrelid
                JOIN pg_class p ON p.oid = inh.inhparent
                JOIN pg_namespace n ON n.oid = p.relnamespace
                WHERE p.relname = cfg.table_name
                  AND n.nspname = 'public'
                  AND c.relname ~ ('^' || cfg.table_name || '_p[0-9]+$')
            LOOP
                BEGIN
                    IF cfg.partition_interval = 'year' THEN
                        child_period := to_date(right(child_rec.relname, 4), 'YYYY');
                    ELSE
                        child_period := to_date(right(child_rec.relname, 6), 'YYYYMM');
                    END IF;
                EXCEPTION WHEN others THEN
                    CONTINUE;  -- name didn't parse as a period; leave it alone
                END;

                IF (child_period + step) <= cutoff THEN
                    IF cfg.retention_action = 'drop' THEN
                        EXECUTE format('DROP TABLE IF EXISTS %I', child_rec.relname);
                    ELSE
                        EXECUTE format('ALTER TABLE %I DETACH PARTITION %I',
                                       cfg.table_name, child_rec.relname);
                    END IF;
                END IF;
            END LOOP;
        END IF;
    END LOOP;
END;
$_$;

-- Name: FUNCTION ensure_partitions(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.ensure_partitions() IS 'Pre-creates current + premake future partitions and retires old ones for every table in partition_config. Called daily by the maintenance worker.';

-- Name: next_queue_token_seq(uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.next_queue_token_seq(p_tenant_id uuid, p_department_id uuid, p_date date DEFAULT CURRENT_DATE) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_seq INT;
BEGIN
    SELECT COALESCE(MAX(token_seq), 0) + 1 INTO v_seq
    FROM queue_tokens
    WHERE tenant_id = p_tenant_id
      AND department_id = p_department_id
      AND token_date = p_date;
    RETURN v_seq;
END;
$$;

CREATE FUNCTION public.notify_notification_created() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Keep the payload well under Postgres's ~8000-byte NOTIFY limit: the body
    -- is truncated (the full row is always available via the REST feed).
    PERFORM pg_notify(
        'notification_created',
        json_build_object(
            'id', NEW.id,
            'tenant_id', NEW.tenant_id,
            'user_id', NEW.user_id,
            'kind', NEW.kind,
            'title', left(NEW.title, 2000),
            'body', left(NEW.body, 4000),
            'category', NEW.category,
            'entity_type', NEW.entity_type,
            'entity_id', NEW.entity_id,
            'action_url', NEW.action_url
        )::text
    );
    RETURN NEW;
END;
$$;

CREATE FUNCTION public.prevent_camp_physical_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF current_setting('app.allow_physical_delete', true) = 'true' THEN
        RETURN OLD;
    END IF;

    RAISE EXCEPTION 'physical delete is disabled for public.%; set deleted_at/deleted_by/delete_reason instead', TG_TABLE_NAME
        USING ERRCODE = 'check_violation';
END;
$$;

CREATE FUNCTION public.soft_delete_guardrail() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
    user_uuid uuid;
    set_clause text;
BEGIN
    IF current_setting('app.allow_physical_delete', true) = 'true' THEN
        RETURN OLD;
    END IF;

    user_uuid := NULLIF(current_setting('app.user_id', true), '')::uuid;
    set_clause :=
        'deleted_at = COALESCE(deleted_at, now()), ' ||
        'deleted_by = COALESCE(deleted_by, $1), ' ||
        'delete_reason = COALESCE(delete_reason, $2)';

    IF EXISTS (
        SELECT 1
        FROM information_schema.columns
        WHERE table_schema = TG_TABLE_SCHEMA
          AND table_name = TG_TABLE_NAME
          AND column_name = 'updated_at'
    ) THEN
        set_clause := set_clause || ', updated_at = now()';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM information_schema.columns
        WHERE table_schema = TG_TABLE_SCHEMA
          AND table_name = TG_TABLE_NAME
          AND column_name = 'is_active'
    ) THEN
        set_clause := set_clause || ', is_active = false';
    END IF;

    EXECUTE format(
        'UPDATE %I.%I SET %s WHERE ctid = $3 AND deleted_at IS NULL',
        TG_TABLE_SCHEMA,
        TG_TABLE_NAME,
        set_clause
    )
    USING user_uuid, 'Soft deleted by database guardrail', OLD.ctid;

    RETURN NULL;
END;
$_$;

